require "test_helper"

class ZzEdgeTest < ActiveSupport::TestCase
  setup { @book = books(:manual) }

  def count(&block)
    assert_enqueued_jobs(0, only: AnnouncePublicationJob) { }  # no-op, ensures helper ok
    before = enqueued_jobs.count { |j| j["job_class"] == "AnnouncePublicationJob" }
    block.call
    enqueued_jobs.count { |j| j["job_class"] == "AnnouncePublicationJob" } - before
  end

  test "A go live, then save again in same sitting" do
    n = count { Book.transaction { @book.update!(published: true); @book.update!(slug: "x-slug") } }
    puts "\n[A] live + slug change same sitting: #{n}"
  end

  test "B go live then down within sitting" do
    n = count { Book.transaction { @book.update!(published: true); @book.update!(published: false) } }
    puts "[B] live then down in sitting (ends draft): #{n}"
  end

  test "C down, up, down, up in one sitting from draft" do
    n = count { Book.transaction { 2.times { @book.update!(published: true); @book.update!(published: false) }; @book.update!(published: true) } }
    puts "[C] draft->live->draft->live: #{n}"
  end

  test "D live -> down -> live in one sitting" do
    @book.update_column(:published, true); @book.reload
    n = count { Book.transaction { @book.update!(published: false); @book.update!(published: true) } }
    puts "[D] live->down->live in one sitting: #{n}"
  end

  test "E create live / create draft" do
    n1 = count { Book.create!(title: "Live new", published: true) }
    n2 = count { Book.create!(title: "Draft new") }
    puts "[E] created live: #{n1}, created draft: #{n2}"
  end

  test "F fail after live, then retry same instance" do
    n = count do
      assert_raises(RuntimeError) do
        @book.transaction { @book.update!(published: true); @book.press(Page.new(body: "x"), title: "p"); raise "boom" }
      end
    end
    puts "[F] failed sitting: #{n}; db published=#{@book.reload.published?} mem=#{@book.published?}"
    n2 = count { @book.update!(published: true) }
    puts "[F] retry same instance go live: #{n2}; db=#{@book.reload.published?}"
  end

  test "G savepoint rollback of the go-live" do
    n = count do
      Book.transaction do
        @book.transaction(requires_new: true) { @book.update!(published: true); raise ActiveRecord::Rollback }
      end
    end
    puts "[G] go live inside rolled back savepoint: #{n}; db=#{@book.reload.published?} mem=#{@book.published?}"
  end

  test "H go live in outer, savepoint fails after" do
    n = count do
      Book.transaction do
        @book.update!(published: true)
        @book.transaction(requires_new: true) { raise ActiveRecord::Rollback }
      end
    end
    puts "[H] live in outer, inner savepoint rolled back: #{n}; db=#{@book.reload.published?}"
  end

  test "I touch only on draft and live" do
    n1 = count { @book.press(Page.new(body: ""), title: "draft page") }
    @book.update!(published: true); @book.reload
    n2 = count { @book.press(Page.new(body: ""), title: "live page") }
    puts "[I] add page to draft: #{n1}; add page to live: #{n2}"
  end

  test "J go live with page via leaf path (leaf.book instance)" do
    n = count { Book.transaction { @book.update!(published: true); leaves(:welcome_page).update!(title: "renamed") rescue nil; @book.press(Page.new(body: ""), title: "z") } }
    puts "[J] live + page: #{n}"
  end
end
EOF
